import Blockly from 'blockly/core';
import 'blockly/blocks';
import { pythonGenerator } from 'blockly/python';

// Define the mutator mixin
const ARRAY_MUTATOR_MIXIN = {
  mutationToDom: function() {
    const container = Blockly.utils.xml.createElement('mutation');
    container.setAttribute('items', this.elementCount_);
    return container;
  },

  domToMutation: function(xmlElement) {
    this.elementCount_ = parseInt(xmlElement.getAttribute('items'), 10);
    this.updateShape_();
  },

  decompose: function(workspace) {
    const containerBlock = workspace.newBlock('array_container');
    containerBlock.initSvg();
    let connection = containerBlock.getInput('STACK').connection;
    
    for (let i = 0; i < this.elementCount_; i++) {
      const itemBlock = workspace.newBlock('array_element');
      itemBlock.initSvg();
      connection.connect(itemBlock.previousConnection);
      connection = itemBlock.nextConnection;
    }
    
    return containerBlock;
  },

  compose: function(containerBlock) {
    let itemBlock = containerBlock.getInputTargetBlock('STACK');
    const connections = [];
    const values = [];
    
    while (itemBlock && !itemBlock.isInsertionMarker()) {
      connections.push(itemBlock.valueConnection_);
      values.push(itemBlock.getFieldValue('ELEMENT_VALUE'));
      itemBlock = itemBlock.nextConnection && itemBlock.nextConnection.targetBlock();
    }
    
    this.elementCount_ = connections.length;
    this.updateShape_();
    
    // Reconnect blocks and restore values
    for (let i = 0; i < this.elementCount_; i++) {
      if (connections[i]) {
        this.getInput('ELEMENT' + i).connection.connect(connections[i]);
      }
      if (values[i]) {
        this.setFieldValue(values[i], 'ELEMENT_VALUE' + i);
      }
    }
  },

  saveConnections: function(containerBlock) {
    let itemBlock = containerBlock.getInputTargetBlock('STACK');
    let i = 0;
    while (itemBlock) {
      const input = this.getInput('ELEMENT' + i);
      itemBlock.valueConnection_ = input && input.connection.targetConnection;
      itemBlock = itemBlock.nextConnection && itemBlock.nextConnection.targetBlock();
      i++;
    }
  },

  updateShape_: function() {
    // Remove any existing ELEMENT inputs
    for (let i = 0; i < this.elementCount_; i++) {
      if (this.getInput('ELEMENT' + i)) {
        this.removeInput('ELEMENT' + i);
      }
    }

    // Add new ELEMENT inputs
    for (let i = 0; i < this.elementCount_; i++) {
      this.appendValueInput('ELEMENT' + i)
        .setCheck(null)
        .appendField(i === 0 ? 'with element' : 'and element');
    }
  }
};

// Register the mutator
Blockly.Extensions.registerMutator('array_mutator',
  ARRAY_MUTATOR_MIXIN,
  function() {
    this.elementCount_ = 1;
    this.updateShape_();
  },
  ['array_element']
);

Blockly.Blocks['array_create'] = {
  init: function() {
    this.appendDummyInput()
        .appendField('create array');
    this.setColour("#c70303");
    this.setTooltip('Create an array with elements');
    this.setDeletable(true);
    this.setMovable(true);
    
    // Initialize with one element
    this.elementCount_ = 1;
    this.updateShape_();

    // Set up the mutator
    this.mutator = new Blockly.Mutator(['array_element']);
  },

  mutationToDom: function() {
    const container = Blockly.utils.xml.createElement('mutation');
    container.setAttribute('items', this.elementCount_);
    return container;
  },

  domToMutation: function(xmlElement) {
