      itemBlock = itemBlock.nextConnection && itemBlock.nextConnection.targetBlock();
    }
    
    this.elementCount_ = connections.length;
    this.updateShape_();
    
    // Reconnect blocks and restore values
    for (let i = 0; i < this.elementCount_; i++) {
      if (connections[i]) {
        this.getInput('ELEMENT' + i).connection.connect(connections[i]);
      }
      if (values[i]) {
        this.setFieldValue(values[i], 'ELEMENT_VALUE' + i);
      }
    }
  },

  saveConnections: function(containerBlock) {
    let itemBlock = containerBlock.getInputTargetBlock('STACK');
    let i = 0;
    while (itemBlock) {
      const input = this.getInput('ELEMENT' + i);
      itemBlock.valueConnection_ = input && input.connection.targetConnection;
      itemBlock = itemBlock.nextConnection && itemBlock.nextConnection.targetBlock();
      i++;
    }
  },

  updateShape_: function() {
    // Remove any existing ELEMENT inputs
    for (let i = 0; i < this.elementCount_; i++) {
      if (this.getInput('ELEMENT' + i)) {
        this.removeInput('ELEMENT' + i);
      }
    }

    // Add new ELEMENT inputs
    for (let i = 0; i < this.elementCount_; i++) {
      this.appendValueInput('ELEMENT' + i)
        .setCheck(null)
        .appendField(i === 0 ? 'with element' : 'and element');
    }
  }
};

Blockly.Blocks['array_container'] = {
  init: function() {
    this.setColour("#c70303");
    this.appendDummyInput()
        .appendField('array');
    this.appendStatementInput('STACK');
    this.setTooltip('Add, remove, or reorder elements to reconfigure this array');
    this.contextMenu = false;
  }
};

Blockly.Blocks['array_element'] = {
  init: function() {
    this.setColour("#c70303");
    this.appendDummyInput()
        .appendField('element');
    this.setPreviousStatement(true);
    this.setNextStatement(true);
    this.setTooltip('Add an element to the array');
    this.contextMenu = false;
  }
};

pythonGenerator.forBlock['array_create'] = function(block) {
  var elements = [];
  for (var i = 0; i < block.elementCount_; i++) {
    var element = pythonGenerator.valueToCode(block, 'ELEMENT' + i,
        pythonGenerator.ORDER_NONE) || 'None';
    elements.push(element);
  }
  var code = '[' + elements.join(', ') + ']';
  return [code, pythonGenerator.ORDER_ATOMIC];
};

Blockly.Blocks['arrays_get'] = {
  init: function() {
    this.appendValueInput('ARRAY')
        .setCheck(null)
        .appendField('get element at index');
    this.appendValueInput('INDEX')
        .setCheck('Number');
    this.setOutput(true, null);
    this.setColour(160);
    this.setTooltip('Get an element from the array at the specified index');
  }
};

pythonGenerator.forBlock['arrays_get'] = function(block) {
  const array = pythonGenerator.valueToCode(block, 'ARRAY', pythonGenerator.ORDER_MEMBER) || '[]';
  const index = pythonGenerator.valueToCode(block, 'INDEX', pythonGenerator.ORDER_ATOMIC) || '0';
  const code = array + '[' + index + ']';
  return [code, pythonGenerator.ORDER_MEMBER];
};

Blockly.Blocks['arrays_set'] = {
  init: function() {
    this.appendValueInput('ARRAY')
        .setCheck(null)
        .appendField('set element at index');
    this.appendValueInput('INDEX')
        .setCheck('Number');
    this.appendValueInput('VALUE')
        .appendField('to');
    this.setPreviousStatement(true, null);
    this.setNextStatement(true, null);
    this.setColour(160);
    this.setTooltip('Set an element in the array at the specified index');
  }
};

pythonGenerator.forBlock['arrays_set'] = function(block) {
  const array = pythonGenerator.valueToCode(block, 'ARRAY', pythonGenerator.ORDER_MEMBER) || '[]';
  const index = pythonGenerator.valueToCode(block, 'INDEX', pythonGenerator.ORDER_ATOMIC) || '0';
  const value = pythonGenerator.valueToCode(block, 'VALUE', pythonGenerator.ORDER_ATOMIC) || 'None';
  return array + '[' + index + '] = ' + value + '\n';
};

Blockly.Blocks['arrays_length'] = {
  init: function() {
    this.appendValueInput('ARRAY')
        .setCheck(null)
        .appendField('length of');
    this.setOutput(true, 'Number');
    this.setColour(160);
    this.setTooltip('Get the length of the array');
  }
};

pythonGenerator.forBlock['arrays_length'] = function(block) {
  const array = pythonGenerator.valueToCode(block, 'ARRAY', pythonGenerator.ORDER_MEMBER) || '[]';
  const code = 'len(' + array + ')';
  return [code, pythonGenerator.ORDER_FUNCTION_CALL];
};
